<?php
if (session_status() === PHP_SESSION_NONE) session_start();
if (!isset($_SESSION['id_usuario']) || ($_SESSION['rol'] ?? '') !== 'admin') { header('Location: login.php'); exit; }
require_once 'conexion.php';
$tituloPagina = 'Panel de administración | Indicador de Agua';
$aviso = ''; $tipoAviso = 'success';
if (empty($_SESSION['csrf_admin'])) $_SESSION['csrf_admin'] = bin2hex(random_bytes(32));
function e($v) { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $token = $_POST['csrf_token'] ?? '';
    if (!hash_equals($_SESSION['csrf_admin'], $token)) {
        $aviso = 'La sesión del formulario venció. Actualiza la página e inténtalo nuevamente.'; $tipoAviso = 'error';
    } else {
        $accion = $_POST['accion'] ?? '';
        if ($accion === 'cambiar_rol') {
            $id = filter_input(INPUT_POST, 'id_usuario', FILTER_VALIDATE_INT);
            $rol = $_POST['rol'] ?? '';
            if (!$id || !in_array($rol, ['usuario','admin'], true)) { $aviso='Los datos del usuario no son válidos.'; $tipoAviso='error'; }
            elseif ((int)$id === (int)$_SESSION['id_usuario'] && $rol !== 'admin') { $aviso='No puedes quitarte el rol de administrador mientras tienes esta sesión abierta.'; $tipoAviso='error'; }
            else { $st=$conexion->prepare('UPDATE usuarios SET rol=? WHERE id_usuario=?'); $st->bind_param('si',$rol,$id); $st->execute(); $aviso=$st->affected_rows >= 0 ? 'Rol del usuario actualizado.' : 'No se pudo actualizar el rol.'; $st->close(); }
        } elseif ($accion === 'eliminar_contacto') {
            $id = filter_input(INPUT_POST, 'id_contacto', FILTER_VALIDATE_INT);
            if ($id) { $st=$conexion->prepare('DELETE FROM contactos WHERE id_contacto=?'); $st->bind_param('i',$id); $st->execute(); $st->close(); $aviso='Mensaje eliminado.'; }
            else { $aviso='El mensaje seleccionado no es válido.'; $tipoAviso='error'; }
        } elseif ($accion === 'eliminar_imagen') {
            $id = filter_input(INPUT_POST, 'id_imagen', FILTER_VALIDATE_INT);
            if ($id) { $st=$conexion->prepare('DELETE FROM galeria WHERE id_imagen=?'); $st->bind_param('i',$id); $st->execute(); $st->close(); $aviso='Imagen quitada de la galería. El archivo original no se borró.'; }
            else { $aviso='La imagen seleccionada no es válida.'; $tipoAviso='error'; }
        }
    }
}
function total($conexion, $sql) { $r=$conexion->query($sql); return $r ? (int)$r->fetch_assoc()['total'] : 0; }
$totalUsuarios=total($conexion,'SELECT COUNT(*) AS total FROM usuarios');
$totalContactos=total($conexion,'SELECT COUNT(*) AS total FROM contactos');
$totalMediciones=total($conexion,'SELECT COUNT(*) AS total FROM mediciones');
$totalGaleria=total($conexion,'SELECT COUNT(*) AS total FROM galeria');
$usuarios=$conexion->query('SELECT id_usuario,nombre,correo,rol,fecha_registro FROM usuarios ORDER BY fecha_registro DESC');
$contactos=$conexion->query('SELECT id_contacto,nombre,correo,asunto,mensaje,fecha_registro FROM contactos ORDER BY fecha_registro DESC LIMIT 30');
$mediciones=$conexion->query('SELECT consumo_litros,humedad,agua_ahorrada,eficiencia,fecha_medicion FROM mediciones ORDER BY fecha_medicion DESC LIMIT 10');
$imagenes=$conexion->query('SELECT id_imagen,titulo,ruta_imagen,descripcion,fecha_registro FROM galeria ORDER BY fecha_registro DESC');
include 'includes/header.php';
?>
